const workflow = $input.first().json;

const suspiciousKeys = {
  secrets: [
    'password',
    'passwd',
    'pwd',
    'secret',
    'api_key',
    'apikey',
    'apiKey',
    'access_token',
    'accessToken',
    'auth_token',
    'authToken',
    'client_secret',
    'clientSecret',
    'private_key',
    'privateKey',
    'token'
  ],

  n8nMetadata: {
    webhookId: 'webhook_identifier',
    dataTableId: 'datatable_identifier',
    cachedResultUrl: 'datatable_url',
    instanceId: 'instance_identifier',
    versionId: 'workflow_version_identifier'
  }
};

const findings = [];


// --------------------------------------------------
// DETECCIÓN DE PATRONES POR VALOR
// --------------------------------------------------
// Esta función queda preparada para la Capa 2.
// Por ahora no detectamos patrones adicionales.
// --------------------------------------------------

function detectValuePattern(value) {

  // Solo analizamos valores de tipo string.
  if (typeof value !== 'string') {
    return null;
  }

   // CONNECTION STRINGS
  const connectionStringPattern =
  /\b(?:postgres(?:ql)?|mysql|mongodb(?:\+srv)?)\:\/\/[^\/\s:@]+:[^\/\s@]+@[^\/\s]+/i;

  if (connectionStringPattern.test(value)) {
    return 'connection_string';
  }

  // URL WITH CREDENTIALS
  const urlCredentialsPattern =
    /\bhttps?:\/\/[^\/\s:@]+:[^\/\s@]+@[^\/\s]+/i;

  if (urlCredentialsPattern.test(value)) {
    return 'url_credentials';
  }

  // JWT
  const jwtPattern =
    /\beyJ[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*\.[a-zA-Z0-9_-]*\b/;

  if (jwtPattern.test(value)) {
    return 'jwt';
  }

  // ----------------------------------------------
// BASIC AUTHENTICATION
// ----------------------------------------------

const basicAuthPattern =
  /\bBasic\s+[A-Za-z0-9+/]+={0,2}\b/i;

if (basicAuthPattern.test(value)) {
  return 'basic_auth';
}

  // ----------------------------------------------
  // PRIVATE KEYS
  // ----------------------------------------------

  const privateKeyPattern =
    /-----BEGIN [A-Z0-9 ]*PRIVATE KEY-----/;

  if (privateKeyPattern.test(value)) {
    return 'private_key';
  }

  // ----------------------------------------------
  // BEARER TOKENS
  // ----------------------------------------------

  const bearerTokenPattern =
    /\bBearer\s+\S+/i;

  if (bearerTokenPattern.test(value)) {
    return 'bearer_token';
  }


  return null;
}


// --------------------------------------------------
// RECORRIDO RECURSIVO DEL WORKFLOW
// --------------------------------------------------

function scan(value, path = '', insideCredentials = false) {

  // Arrays
  if (Array.isArray(value)) {

    value.forEach((item, index) => {

      scan(
        item,
        `${path}[${index}]`,
        insideCredentials
      );

    });

    return;
  }


  // Objects
  if (value !== null && typeof value === 'object') {

    for (const [key, child] of Object.entries(value)) {

      const currentPath = path
        ? `${path}.${key}`
        : key;

      let type = null;


      // ----------------------------------------------
      // 1. DETECTAR SECRETOS POR NOMBRE DE CAMPO
      // ----------------------------------------------

      if (suspiciousKeys.secrets.includes(key)) {
        type = 'secret';
      }


      // ----------------------------------------------
      // 2. DETECTAR METADATA ESPECÍFICA DE N8N
      // ----------------------------------------------

      if (suspiciousKeys.n8nMetadata[key]) {
        type = suspiciousKeys.n8nMetadata[key];
      }


      // ----------------------------------------------
      // 3. DETECTAR ID DE CREDENCIAL
      // ----------------------------------------------

      if (
        insideCredentials &&
        key === 'id'
      ) {
        type = 'credential_identifier';
      }


      // ----------------------------------------------
      // 4. DETECTAR PATRONES EN EL VALOR
      // ----------------------------------------------

      const valuePattern = detectValuePattern(child);

      if (valuePattern) {
        type = valuePattern;
      }


      // ----------------------------------------------
      // REGISTRAR HALLAZGO
      // ----------------------------------------------

      if (type) {

        findings.push({
          path: currentPath,
          key,
          type,
          value: child
        });


        // Si encontramos dataTableId, no seguimos
        // recorriendo su contenido para evitar
        // detectar cachedResultUrl por separado.
        if (type === 'datatable_identifier') {
          continue;
        }
      }


      // ----------------------------------------------
      // DETERMINAR CONTEXTO DE CREDENTIALS
      // ----------------------------------------------

      const nextInsideCredentials =
        insideCredentials || key === 'credentials';


      scan(
        child,
        currentPath,
        nextInsideCredentials
      );
    }
  }
}


// --------------------------------------------------
// INICIAR ESCANEO
// --------------------------------------------------

scan(workflow);


// --------------------------------------------------
// RESULTADO
// --------------------------------------------------

return [
  {
    json: {
      originalWorkflow: workflow,
      findings,
      totalFindings: findings.length
    }
  }
];

const input = $input.first().json;

const originalWorkflow = input.originalWorkflow;
const findings = input.findings;


// Crear una copia independiente del workflow.
// De esta forma nunca modificamos originalWorkflow.
const sanitizedWorkflow = JSON.parse(
  JSON.stringify(originalWorkflow)
);


// Reemplazar un valor utilizando su ruta dentro del objeto.
function replaceAtPath(object, path, newValue) {

  const parts = path
    .replace(/\[(\d+)\]/g, '.$1')
    .split('.');

  let current = object;

  for (let i = 0; i < parts.length - 1; i++) {
    current = current[parts[i]];
  }

  current[parts[parts.length - 1]] = newValue;
}


// Procesar cada hallazgo.
for (const finding of findings) {

  switch (finding.type) {

      case 'connection_string':

  replaceAtPath(
    sanitizedWorkflow,
    finding.path,
    '[REDACTED_CONNECTION_STRING]'
  );

  break;


case 'url_credentials':

  replaceAtPath(
    sanitizedWorkflow,
    finding.path,
    '[REDACTED_URL_CREDENTIALS]'
  );

  break;


case 'jwt':

  replaceAtPath(
    sanitizedWorkflow,
    finding.path,
    '[REDACTED_JWT]'
  );

  break;

    case 'basic_auth':

  replaceAtPath(
    sanitizedWorkflow,
    finding.path,
    '[REDACTED_BASIC_AUTH]'
  );

  break;

    case 'bearer_token':

  replaceAtPath(
    sanitizedWorkflow,
    finding.path,
    '[REDACTED_BEARER_TOKEN]'
  );

  break;


    case 'private_key':

  replaceAtPath(
        sanitizedWorkflow,
        finding.path,
       '[REDACTED_PRIVATE_KEY]'
      );

      break;

    case 'webhook_identifier':

      replaceAtPath(
        sanitizedWorkflow,
        finding.path,
        '[REDACTED_WEBHOOK_ID]'
      );

      break;


    case 'workflow_version_identifier':

      replaceAtPath(
        sanitizedWorkflow,
        finding.path,
        '[REDACTED_VERSION_ID]'
      );

      break;


    case 'instance_identifier':

      replaceAtPath(
        sanitizedWorkflow,
        finding.path,
        '[REDACTED_INSTANCE_ID]'
      );

      break;


    case 'credential_identifier':

      replaceAtPath(
        sanitizedWorkflow,
        finding.path,
        '[REDACTED_CREDENTIAL_ID]'
      );

      break;


    case 'datatable_identifier': {

      // Obtener la ruta del objeto dataTableId
      const dataTablePath = finding.path;

      // Buscar el objeto correspondiente dentro
      // del workflow sanitizado.
      const parts = dataTablePath
        .replace(/\[(\d+)\]/g, '.$1')
        .split('.');

      let current = sanitizedWorkflow;

      for (const part of parts) {
        current = current[part];
      }

      // Mantener la estructura original y modificar
      // solamente los valores sensibles.
      if (
        current &&
        typeof current === 'object'
      ) {

        if ('value' in current) {
          current.value = '[REDACTED_DATATABLE_ID]';
        }

        if ('cachedResultUrl' in current) {
          current.cachedResultUrl =
            '[REDACTED_DATATABLE_URL]';
        }
      }

      break;
    }
  }
}


return [
  {
    json: sanitizedWorkflow
  }
];
